-- ============================================================
-- SPINBOT FUNCTIONS
-- ============================================================
local function stopSpinbot()
    Config.Enabled = false
    spinbotReady = false

    if savedAutoRotate ~= nil and humanoid and apiOffsets then
        pcall(memory_write, "byte", humanoid.Address + apiOffsets.Humanoid.AutoRotate, savedAutoRotate)
        savedAutoRotate = nil
    end

    if loopConnection then
        loopConnection:Disconnect()
        loopConnection = nil
    end
end

local function initSpinbot()
    local waited = 0
    while (not LocalPlayer.Character or not LocalPlayer.Character:FindFirstChild("HumanoidRootPart")) and waited < 2 do
        wait(0.1)
        waited = waited + 0.1
    end

    character = LocalPlayer.Character
    if not character then return false end
    rootPart = character:FindFirstChild("HumanoidRootPart")
    humanoid = character:FindFirstChild("Humanoid")
    if not rootPart or not humanoid then return false end

    if not apiOffsets then
        local ok, response = pcall(httpget, "https://imtheo.lol/Offsets/Offsets.json")
        if not ok or not response then return false end

        local decodeOk, decoded = pcall(function()
            return game:GetService("HttpService"):JSONDecode(response)
        end)
        if not decodeOk or not decoded or not decoded.Offsets then return false end
        apiOffsets = decoded.Offsets
    end

    local readOk, originalValue = pcall(memory_read, "byte", humanoid.Address + apiOffsets.Humanoid.AutoRotate)
    if readOk and originalValue ~= nil then
        savedAutoRotate = originalValue
    else
        savedAutoRotate = 1
    end

    pcall(memory_write, "byte", humanoid.Address + apiOffsets.Humanoid.AutoRotate, 0)

    primitiveOffset = nil
    for offset = 8, 1024, 8 do
        local readOk2, ptr = pcall(memory_read, "uintptr_t", rootPart.Address + offset)
        if readOk2 and ptr and ptr > 10000 then
            local posOk, posX = pcall(memory_read, "float", ptr + apiOffsets.Primitive.Position)
            if posOk and type(posX) == "number" and math.abs(posX - rootPart.Position.X) < 0.1 then
                primitiveOffset = offset
                break
            end
        end
    end

    if not primitiveOffset then return false end
    spinbotReady = true
    return true
end

local function startLoop()
    if loopConnection then return end
    if not spinbotReady then return end
    if not apiOffsets or not primitiveOffset then return end

    local angVelOffset = apiOffsets.Primitive.AssemblyAngularVelocity

    loopConnection = RunService.Stepped:Connect(function(deltaTime)
        if isUnloaded then
            stopSpinbot()
            return
        end
        if not Config.Enabled then
            stopSpinbot()
            return
        end
        if not character or not character:IsDescendantOf(workspace) then
            stopSpinbot()
            return
        end
        if humanoid.Health <= 0 then
            stopSpinbot()
            return
        end

        local prim = memory_read("uintptr_t", rootPart.Address + primitiveOffset)
        if prim and prim > 10000 then
            local targetX = prim + angVelOffset
            for _ = 1, 2000 do
                memory_write("float", targetX, 0)
                memory_write("float", targetX + 4, Config.Speed)
                memory_write("float", targetX + 8, 0)
            end
        end
    end)
end

