local function setMenuVisible(visible)
    menuVisible = visible
    for _, obj in ipairs(allMenuObjects) do
        if obj then
            obj.Visible = visible
        end
    end
end

-- ============================================================
-- CALLBACKS
-- ============================================================
function onClick()
    if isUnloaded then return end
    isUnloaded = true
    stopSpinbot()

    for _, obj in ipairs(allMenuObjects) do
        pcall(function()
            if obj and obj.Remove then
                obj:Remove()
            end
        end)
    end

    shouldExit = true
end

function onChanged(value)
    if isUnloaded then return end
    Config.SliderValue = value
    Config.Speed = value * SPEED_MULTIPLIER
end

function onKeyChanged(keyCode)
    if isUnloaded then return end
    if keyCode and keyCode > 0 then
        Keybind5_Key = keyCode
        local keyName = KeyNames[keyCode] or ("Key " .. tostring(keyCode))
        Keybind5_Text.Text = "[ " .. keyName .. " ]"
        notify("Keybind changed to " .. keyName, "Spinbot", 2)
    end
end

-- ============================================================
-- TOGGLE
-- ============================================================
local function toggleSpinbot(pressedKeyName)
    if isUnloaded then return end
    if isInitializing then return end

    if not Config.Enabled then
        if not spinbotReady then
            isInitializing = true
            local ok = pcall(function()
                local success = initSpinbot()
                if success then
                    Config.Enabled = true
                    startLoop()
                    notify("Spinbot ON", "Activated by: " .. pressedKeyName, 2)
                else
                    notify("Init error (dead?)", "Error", 3)
                end
            end)
            if not ok then
                notify("Error in initSpinbot", "Error", 3)
            end
            isInitializing = false
        else
            Config.Enabled = true
            startLoop()
            notify("Spinbot ON", "Activated by: " .. pressedKeyName, 2)
        end
    else
        stopSpinbot()
        notify("Spinbot OFF", "Activated by: " .. pressedKeyName, 2)
    end
end

-- ============================================================
-- INITIAL NOTIFICATION
-- ============================================================
notify("Spinbot loaded. F2 - hide/show menu", "Matcha GUI", 5)

-- ============================================================
-- INPUT HANDLING
-- ============================================================
local dragging = nil
local dragStart = nil
local startPos = nil
local lastMouse1 = false
local lastKeyState = false
local lastF2State = false

local lastToggleTime = 0
local TOGGLE_COOLDOWN = 0.3

local F2_VK = 0x71

while not shouldExit do
    wait(0.01)
    if isrbxactive() and not isUnloaded then
        local mouse1 = ismouse1pressed()
        local mPos = Vector2.new(Mouse.X, Mouse.Y)
        local keyPressed = iskeypressed(Keybind5_Key)
        local f2Pressed = iskeypressed(F2_VK)

        -- F2: hide/show menu
        if f2Pressed and not lastF2State then
            setMenuVisible(not menuVisible)
        end
        lastF2State = f2Pressed

        -- Key rebinding logic
        if Keybind5_IsListening then
            for i = 1, 255 do
                if iskeypressed(i) and not ismouse1pressed() then
                    Keybind5_Key = i
                    Keybind5_IsListening = false
                    local keyName = KeyNames[i] or ("Key " .. tostring(i))
                    Keybind5_Text.Text = "[ " .. keyName .. " ]"
                    Keybind5_Text.Color = Color3.fromHex("#ffffff")
                    pcall(function() onKeyChanged(i) end)
                    wait(0.2)
                    break
                end
            end
        else
            -- Spinbot activation with cooldown check
            if keyPressed and not lastKeyState then
                local currentTime = os.clock()
                if currentTime - lastToggleTime > TOGGLE_COOLDOWN then
                    local kName = KeyNames[Keybind5_Key] or ("Key " .. tostring(Keybind5_Key))
                    toggleSpinbot(kName)
                    lastToggleTime = currentTime
                end
            end
        end
        lastKeyState = keyPressed

        -- Mouse clicks handling (only if menu is visible)
        if mouse1 and not lastMouse1 and menuVisible then
            if Keybind5.Visible and mPos.X >= Keybind5.Position.X and mPos.X <= Keybind5.Position.X + Keybind5.Size.X and
               mPos.Y >= Keybind5.Position.Y and mPos.Y <= Keybind5.Position.Y + Keybind5.Size.Y then
                Keybind5_IsListening = true
                Keybind5_Text.Text = "..."
                Keybind5_Text.Color = Color3.fromHex("#FFFF00")
            end
            if Button8.Visible and mPos.X >= Button8.Position.X and mPos.X <= Button8.Position.X + Button8.Size.X and
               mPos.Y >= Button8.Position.Y and mPos.Y <= Button8.Position.Y + Button8.Size.Y then
                onClick()
            end
            if Square3.Visible and mPos.X >= Square3.Position.X and mPos.X <= Square3.Position.X + Square3.Size.X and
               mPos.Y >= Square3.Position.Y and mPos.Y <= Square3.Position.Y + Square3.Size.Y then
                dragging = Square3
                dragStart = mPos
                startPos = Square3.Position
            end
            if Slider6_Knob.Visible and mPos.X >= Slider6_Knob.Position.X and mPos.X <= Slider6_Knob.Position.X + Slider6_Knob.Size.X and
               mPos.Y >= Slider6_Knob.Position.Y and mPos.Y <= Slider6_Knob.Position.Y + Slider6_Knob.Size.Y then
                dragging = Slider6_Knob
                dragStart = mPos
                startPos = Slider6_Knob.Position
            end
        end

        if not mouse1 and lastMouse1 then
            dragging = nil
        end

        if dragging and mouse1 and menuVisible then
            local delta = mPos - dragStart
            dragging.Position = startPos + delta
            if dragging == Slider6_Knob then
                local minX = Slider6.Position.X
                local maxX = Slider6.Position.X + Slider6.Size.X
                if dragging.Position.X < minX then dragging.Position = Vector2.new(minX, dragging.Position.Y) end
                if dragging.Position.X > maxX then dragging.Position = Vector2.new(maxX, dragging.Position.Y) end
                dragging.Position = Vector2.new(dragging.Position.X, Slider6.Position.Y + 5 - dragging.Size.Y/2)
                local percent = (dragging.Position.X - minX) / (Slider6.Size.X)
                local value = 0 + (100 - 0) * percent
                Slider6_Value = value
                Slider6_ValueText.Text = tostring(math.floor(value))
                pcall(function() onChanged(value) end)
            end
            if dragging == Square3 then
                Square3_Border.Position = dragging.Position
                Text4.Position = dragging.Position + Vector2.new(152, 45)
                Keybind5.Position = dragging.Position + Vector2.new(64.5, 175)
                Keybind5_Border.Position = Keybind5.Position
                Keybind5_Text.Position = Keybind5.Position + Vector2.new(171/2, 48/2)
                Slider6.Position = dragging.Position + Vector2.new(54, 132)
                local percent = (Slider6_Value - 0) / (100 - 0)
                Slider6_Knob.Position = Slider6.Position + Vector2.new(192 * percent - 10, 5 - 10)
                Slider6_ValueText.Position = Slider6.Position + Vector2.new(192/2, -10)
                Button8.Position = dragging.Position + Vector2.new(258, 15)
                Button8_Text.Position = Button8.Position + Vector2.new(30/2, 30/2)
            end
        end

        lastMouse1 = mouse1
    end
end